//! The game's schema readers of entity components, goals and event responses: the member trees of
//! [`table`] (generated by `cargo xtask entity-schemas` from the game's schema description) and
//! the validation every such reader runs before it parses.
//!
//! A schema reader validates the whole member tree first: each member is looked up by name (the
//! names are patterns matched whole), then by the JSON type of its value (the first type option
//! that accepts it), and the children's results are combined with a logical and. In the strict
//! mode a member no child names fails the node (`child '%s' not valid here.`); in the lenient mode
//! it is taken out without a word. A value of a type no option takes logs `unknown child schema
//! option type. Allowed types: %s` in both modes and fails the node in the strict mode; the
//! lenient mode takes it out. A missing required child (`Required child %s not found`) and a
//! string an enum node does not know (`Value '%s' not allowed.  Must match at least one of the
//! following keys: %s`) fail the node in both modes. When the validation fails the reader does not
//! parse: the component keeps its defaults and the entity loads with that instance.

pub(crate) mod numeric;
mod numeric_table;
mod table;

use crate::codes;
use bedrock_addon_core::diagnostic::Code;
use std::fmt::Write as _;

use bedrock_addon_core::diagnostic::codes as core_codes;
use bedrock_addon_core::diagnostic::{Diagnostic, Diagnostics, JsonPath, Phase, Severity};
use bedrock_addon_core::json::Value;
use bedrock_addon_core::version::FormatVersion;

/// The JSON types a node accepts, as jsoncpp's value types: null.
pub(crate) const NULL: u8 = 1;
/// A signed integer.
pub(crate) const INT: u8 = 1 << 1;
/// An unsigned integer (`JsonCpp` reads a large positive literal so).
pub(crate) const UINT: u8 = 1 << 2;
/// A number with a fraction or an exponent.
pub(crate) const REAL: u8 = 1 << 3;
/// A string.
pub(crate) const STRING: u8 = 1 << 4;
/// `true` or `false`.
pub(crate) const BOOL: u8 = 1 << 5;
/// An array.
pub(crate) const ARRAY: u8 = 1 << 6;
/// An object.
pub(crate) const OBJECT: u8 = 1 << 7;

/// The format version from which the readers validate strictly: the game reads a document below
/// 1.15.0 in the lenient mode and every later one in the strict mode.
pub(crate) const STRICT_SINCE: FormatVersion = FormatVersion::new(1, 15, 0);

/// One reader: a component, goal or event response and its schema.
#[derive(Debug)]
pub(crate) struct Owner {
    /// The JSON name.
    pub(crate) name: &'static str,
    /// For a migrated reader, the version its typed (cereal) reader starts at: the schema reader
    /// converts the documents below it. `None`: the schema reader reads every version.
    pub(crate) typed_since: Option<(u16, u16, u16)>,
    /// The root's children.
    pub(crate) members: &'static [Member],
}

/// A child: a name pattern and its type options, in order.
#[derive(Debug)]
pub(crate) struct Member {
    /// The pattern (`a|b`, `[a-zA-Z0-9_.:-]+`), matched whole.
    pub(crate) name: &'static str,
    /// Whether its absence fails the node.
    pub(crate) required: bool,
    /// The type options, in order.
    pub(crate) options: &'static [Node],
}

/// A type option of a child.
#[derive(Debug)]
pub(crate) struct Node {
    /// The type name `Allowed types:` prints for it (may be empty).
    pub(crate) type_name: &'static str,
    /// The JSON types the node takes.
    pub(crate) accepts: u8,
    /// Object children.
    pub(crate) members: &'static [Member],
    /// Array element options.
    pub(crate) elements: &'static [Node],
    /// Enum constants.
    pub(crate) values: &'static [&'static str],
    /// Whether an object value is validated against [`members`](Self::members): an object node,
    /// or a typed node read through children. A typed node without children is opaque: its own
    /// parse reads the value (`ItemDescriptor`, a trigger, a filter group).
    pub(crate) children: bool,
}

/// A typed, array or enum [`Node`] (the generated table's constructor).
pub(crate) const fn n(
    type_name: &'static str,
    accepts: u8,
    members: &'static [Member],
    elements: &'static [Node],
    values: &'static [&'static str],
) -> Node {
    Node {
        type_name,
        accepts,
        members,
        elements,
        values,
        children: false,
    }
}

/// An object [`Node`], or a typed node read through children.
pub(crate) const fn o(
    type_name: &'static str,
    accepts: u8,
    members: &'static [Member],
    elements: &'static [Node],
    values: &'static [&'static str],
) -> Node {
    Node {
        type_name,
        accepts,
        members,
        elements,
        values,
        children: true,
    }
}

/// The component or goal reader named `name`.
pub(crate) fn component(name: &str) -> Option<&'static Owner> {
    find(&table::COMPONENTS, name)
}

/// The entity event response named `name`.
pub(crate) fn event_response(name: &str) -> Option<&'static Owner> {
    find(&table::EVENT_RESPONSES, name)
}

/// Every component and goal reader (for the tests that walk the table).
#[cfg(test)]
pub(crate) fn components() -> &'static [Owner] {
    &table::COMPONENTS
}

/// The game table's typed version of the component `name`, for the rows' `typed_table` test:
/// `None` where the table has no reader of the key, `Some(None)` where its reader is never
/// replaced by a typed one.
#[cfg(test)]
#[allow(
    clippy::option_option,
    reason = "the `typed_table` signature: no reader, or a reader never typed"
)]
pub(crate) fn typed_since(name: &str) -> Option<Option<FormatVersion>> {
    component(name).map(|owner| {
        owner
            .typed_since
            .map(|(a, b, c)| FormatVersion::new(a, b, c))
    })
}

fn find(list: &'static [Owner], name: &str) -> Option<&'static Owner> {
    list.binary_search_by(|owner| owner.name.as_bytes().cmp(name.as_bytes()))
        .ok()
        .map(|index| &list[index])
}

impl Owner {
    /// Whether this reader reads a document at `version`: a migrated reader only below its typed
    /// version.
    pub(crate) fn reads(&self, version: FormatVersion) -> bool {
        self.typed_since
            .is_none_or(|(a, b, c)| version < FormatVersion::new(a, b, c))
    }
}

/// What a validation found.
#[derive(Clone, Debug, PartialEq)]
pub(crate) enum Problem {
    /// A member no child names (strict mode only): `child '<name>' not valid here.`
    Unknown {
        /// The member, below the component.
        at: JsonPath,
        /// Its name as written.
        name: String,
    },
    /// A value of a type no option takes: `unknown child schema option type.  Allowed types:
    /// <types>`.
    Type {
        /// The member, below the component.
        at: JsonPath,
        /// Each option's type name as ` '<name>'`, in order.
        allowed: String,
    },
    /// A required child the object lacks: `Required child <name> not found`.
    Missing {
        /// The object, below the component.
        at: JsonPath,
        /// The child's name pattern.
        name: &'static str,
    },
    /// A legacy goal's number out of its bound ([`numeric`]): the row's text with the
    /// value; the member takes its default.
    Numeric {
        /// The member, below the goal.
        at: JsonPath,
        /// The row's text, the value's place as `{}`.
        template: &'static str,
        /// The value as the game prints it (`%d`, `%.4f`).
        value: String,
    },
    /// A string an enum node does not know: `Value '<value>' not allowed.  Must match at least one
    /// of the following keys: <keys>`.
    Enum {
        /// The member, below the component.
        at: JsonPath,
        /// The value as written.
        value: String,
        /// The keys, as the game lists them.
        keys: String,
    },
}

impl Problem {
    /// Where, below the component.
    pub(crate) fn at(&self) -> &JsonPath {
        match self {
            Self::Unknown { at, .. }
            | Self::Type { at, .. }
            | Self::Missing { at, .. }
            | Self::Numeric { at, .. }
            | Self::Enum { at, .. } => at,
        }
    }

    /// The game's line.
    pub(crate) fn code(&self) -> Code {
        match self {
            Self::Unknown { name, .. } => core_codes::CHILD_NOT_VALID.with([name.as_str()]),
            Self::Type { allowed, .. } => core_codes::UNKNOWN_CHILD_OPTION.with([allowed.as_str()]),
            Self::Missing { name, .. } => core_codes::REQUIRED_CHILD.with([*name]),
            // One row of the numeric table per goal member: its sentence, the value in it.
            Self::Numeric {
                template, value, ..
            } => core_codes::INVALID_VALUE_WORDED.with([template.replacen("{}", value, 1)]),
            Self::Enum { value, keys, .. } => {
                codes::ENUM_NOT_ALLOWED.with([value.as_str(), keys.as_str()])
            }
        }
    }
}

/// The outcome of [`validate`].
#[derive(Debug, Default)]
pub(crate) struct Outcome {
    /// What the game logs, in its order.
    pub(crate) problems: Vec<Problem>,
    /// The validation failed: the reader parses nothing and the component keeps its defaults.
    pub(crate) failed: bool,
    /// The JSON the reader parses when it did not fail: the members the lenient mode took out
    /// are gone. `None` when nothing was taken out.
    pub(crate) json: Option<Value>,
    /// The members no child names that the lenient mode took out without a word.
    pub(crate) silent: Vec<JsonPath>,
    /// The lists the lenient mode took elements out of, each with the indices (as written) of
    /// the elements it kept, in order: what is told of an element after the validation is
    /// told at the index the file has (`Diagnostics::left_out`).
    pub(crate) left_out: Vec<(JsonPath, Vec<usize>)>,
    /// When the validation failed, the component's members as written: the game parses none.
    pub(crate) unread: Vec<JsonPath>,
}

impl Outcome {
    /// What the entity loader tells of the validation, at paths below `at`: each game line as a
    /// kept error (the game logs it at the error level and loads the entity) with its text, a
    /// failed validation's `ValueRewritten` information at the component (its members are written
    /// back as the defaults), and each member the lenient mode took out without a word as an
    /// information (the game writes no content-log line for it).
    pub(crate) fn findings(&self, at: &JsonPath, phase: Phase) -> Diagnostics {
        let mut found = Diagnostics::default();
        let place = |below: &JsonPath| at.join(below);
        for problem in &self.problems {
            found.push_kept_error(
                Diagnostic::error(problem.code())
                    .at(place(problem.at()))
                    .phase(phase),
            );
        }
        if self.failed {
            // The crate's information at the component (the game writes no content-log line for
            // it): the write-back writes its defaults, so every member of the file it held is
            // rewritten there; and at each member, that it is not read.
            found.push(
                Diagnostic::of(&core_codes::VALUE_REWRITTEN)
                    .at(place(&JsonPath::new()))
                    .phase(phase),
            );
            for below in &self.unread {
                found.push(
                    Diagnostic::of(&core_codes::DROPPED_FIELD)
                        .at(place(below))
                        .phase(phase),
                );
            }
        }
        for below in &self.silent {
            found.push(
                Diagnostic::of(&core_codes::UNRECOGNIZED_FIELD)
                    .severity(Severity::Info)
                    .at(place(below))
                    .phase(phase),
            );
        }
        found
    }

    /// Records the lenient mode's element removals in `found`, at paths below `at` (after the
    /// validation's own findings, which name elements as written).
    pub(crate) fn tell_left_out(&self, at: &JsonPath, found: &mut Diagnostics) {
        for (list, kept) in &self.left_out {
            let path = at.join(list);
            found.left_out(&path, kept);
        }
    }

    /// Runs the numeric checks of the legacy goal `owner` ([`numeric::check`]) over what
    /// its reader parses, when the validation did not fail: their lines follow the validation's,
    /// and the members that failed take their defaults in [`Outcome::replacement`].
    pub(crate) fn check_numbers(&mut self, owner: &str, json: &Value) {
        if self.failed {
            return;
        }
        let parsed = self.json.as_ref().unwrap_or(json);
        let (problems, changed) = numeric::check(owner, parsed);
        self.problems.extend(problems);
        if changed.is_some() {
            self.json = changed;
        }
    }

    /// The JSON the reader reads instead of the component's: `{}` when the validation failed (it
    /// parses nothing: the defaults), the component without what the lenient mode took out;
    /// `None` when it reads the component as it is.
    pub(crate) fn replacement(&self) -> Option<Value> {
        if self.failed {
            Some(Value::from(facet_value::VObject::new()))
        } else {
            self.json.clone()
        }
    }
}

/// Validates `json` (a component's value) against `members` as the game's reader does, in the
/// strict mode or not.
pub(crate) fn validate(members: &'static [Member], json: &Value, strict: bool) -> Outcome {
    let mut cx = Cx {
        strict,
        problems: Vec::new(),
        removed: false,
        silent: Vec::new(),
        left_out: Vec::new(),
    };
    let mut json = json.clone();
    let ok = cx.object(members, &mut json, &JsonPath::new());
    // Each member as written, and each entry of a member that is an object (a map a step may
    // have built from places elsewhere in the file, `offspring.offspring_pairs` of
    // `breeds_with`: told at the entry, the finding names that place).
    let mut unread = Vec::new();
    if !ok && let Some(object) = json.as_object() {
        for (key, value) in object {
            let at = JsonPath::new().child(key.as_str());
            unread.push(at.clone());
            for entry in value.as_object().into_iter().flat_map(|o| o.keys()) {
                let entry_at = at.child(entry.as_str());
                unread.push(entry_at);
            }
        }
    }
    Outcome {
        unread,
        failed: !ok,
        json: (ok && cx.removed).then_some(json),
        problems: cx.problems,
        silent: cx.silent,
        left_out: cx.left_out,
    }
}

struct Cx {
    strict: bool,
    problems: Vec<Problem>,
    removed: bool,
    silent: Vec<JsonPath>,
    left_out: Vec<(JsonPath, Vec<usize>)>,
}

impl Cx {
    /// Validates the members of an object node, then checks that every required child is present.
    fn object(&mut self, members: &'static [Member], json: &mut Value, at: &JsonPath) -> bool {
        let mut ok = true;
        if let Some(object) = json.as_object_mut() {
            let names: Vec<String> = object.keys().map(|k| k.as_str().to_owned()).collect();
            for name in names {
                let here = at.child(&name);
                let Some(value) = object.get_mut(&name) else {
                    continue;
                };
                let keep = match members.iter().find(|m| matches(m.name, &name)) {
                    None => {
                        if self.strict {
                            self.problems.push(Problem::Unknown {
                                at: here,
                                name: name.clone(),
                            });
                            ok = false;
                        } else {
                            self.silent.push(here);
                        }
                        false
                    }
                    Some(member) => {
                        if let Some(child) = self.option(member.options, value, &here) {
                            ok &= child;
                            true
                        } else {
                            ok &= !self.strict;
                            false
                        }
                    }
                };
                if !keep && !self.strict {
                    object.remove(&name);
                    self.removed = true;
                }
            }
        }
        // The game checks the required children only when the members themselves passed.
        if !ok {
            return false;
        }
        for member in members.iter().filter(|m| m.required) {
            let present = json
                .as_object()
                .is_some_and(|object| object.keys().any(|k| matches(member.name, k.as_str())));
            if !present {
                self.problems.push(Problem::Missing {
                    at: at.clone(),
                    name: member.name,
                });
                ok = false;
            }
        }
        ok
    }

    /// The first option of `options` that takes `value`, validated: `Some(its result)`, or `None`
    /// (and the type problem told) when none takes it.
    fn option(
        &mut self,
        options: &'static [Node],
        value: &mut Value,
        at: &JsonPath,
    ) -> Option<bool> {
        let kind = kind_of(value);
        let Some(node) = options.iter().find(|node| node.accepts & kind != 0) else {
            self.problems.push(Problem::Type {
                at: at.clone(),
                allowed: options.iter().fold(String::new(), |mut out, o| {
                    let _ = write!(out, " '{}'", o.type_name);
                    out
                }),
            });
            return None;
        };
        Some(self.node(node, value, at))
    }

    fn node(&mut self, node: &'static Node, value: &mut Value, at: &JsonPath) -> bool {
        if !node.values.is_empty() {
            let Some(text) = value.as_string().map(|s| s.as_str().to_owned()) else {
                return true;
            };
            // The enum node looks the value up lower-cased.
            if node.values.contains(&text.to_lowercase().as_str()) {
                return true;
            }
            // `{} {}\n` per key, the first after "", the others after " or ", in
            // the map's iteration order (the table holds the values in it).
            let keys = node
                .values
                .iter()
                .enumerate()
                .fold(String::new(), |mut out, (i, key)| {
                    let _ = writeln!(out, "{} {key}", if i == 0 { "" } else { " or " });
                    out
                });
            self.problems.push(Problem::Enum {
                at: at.clone(),
                value: text,
                keys,
            });
            return false;
        }
        if node.children && value.is_object() {
            return self.object(node.members, value, at);
        }
        if !node.elements.is_empty()
            && let Some(list) = value.as_array_mut()
        {
            let mut ok = true;
            let mut index = 0;
            let mut place = 0;
            let mut kept = Vec::new();
            while index < list.len() {
                let here = at.index(place);
                let element = &mut list.as_mut_slice()[index];
                match self.option(node.elements, element, &here) {
                    Some(child) => {
                        ok &= child;
                        kept.push(place);
                        index += 1;
                    }
                    None if self.strict => {
                        ok = false;
                        kept.push(place);
                        index += 1;
                    }
                    None => {
                        list.remove(index);
                        self.removed = true;
                    }
                }
                place += 1;
            }
            if kept.len() != place {
                self.left_out.push((at.clone(), kept));
            }
            return ok;
        }
        true
    }
}

/// The `JsonCpp` type of `value`, as an `accepts` bit.
fn kind_of(value: &Value) -> u8 {
    if value.is_null() {
        NULL
    } else if value.is_bool() {
        BOOL
    } else if let Some(number) = value.as_number() {
        if number.is_integer() {
            if number.to_f64_lossy() < 0.0 {
                INT
            } else {
                INT | UINT
            }
        } else {
            REAL
        }
    } else if value.is_string() {
        STRING
    } else if value.is_array() {
        ARRAY
    } else {
        OBJECT
    }
}

/// Whether `name` matches `pattern` whole: `|`-separated alternatives, each a literal or one
/// bracket class followed by `+` (the only pattern the entity schemas use, `[a-zA-Z0-9_.:-]+`).
fn matches(pattern: &str, name: &str) -> bool {
    pattern.split('|').any(|alternative| {
        match alternative
            .strip_prefix('[')
            .and_then(|rest| rest.strip_suffix("]+"))
        {
            Some(class) => !name.is_empty() && name.chars().all(|c| in_class(class, c)),
            None => alternative == name,
        }
    })
}

/// Whether `c` is in the bracket class body `class` (ranges `a-z`, a trailing `-` literal).
fn in_class(class: &str, c: char) -> bool {
    let chars: Vec<char> = class.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if i + 2 < chars.len() && chars[i + 1] == '-' {
            if chars[i] <= c && c <= chars[i + 2] {
                return true;
            }
            i += 3;
        } else {
            if chars[i] == c {
                return true;
            }
            i += 1;
        }
    }
    false
}

#[cfg(test)]
mod tests {
    use super::*;
    use bedrock_addon_core::diagnostic::Severity;

    /// The door's `JsonCpp` scalar profile takes, for each scalar type the table names, the
    /// token types the table's node takes: `int` an integer or real, `float` an integer, real
    /// or bool, `string` a string, `bool` a bool, with no exception in the table.
    #[test]
    fn the_json_cpp_scalar_profile_takes_what_the_table_takes() {
        use bedrock_addon_core::json::{
            BeyondWidth, Declared, ScalarRules, Scalars, Token, Verdict, judge,
        };
        fn nodes<'a>(members: &'a [Member], out: &mut Vec<&'a Node>) {
            for member in members {
                of_options(member.options, out);
            }
        }
        fn of_options<'a>(options: &'a [Node], out: &mut Vec<&'a Node>) {
            for node in options {
                out.push(node);
                nodes(node.members, out);
                of_options(node.elements, out);
            }
        }
        let rules = ScalarRules::PLAIN
            .with_scalars(Scalars::JsonCpp)
            .with_beyond_width(BeyondWidth::Error);
        let tokens = [
            (NULL, Token::Null),
            (INT, Token::Int(-7)),
            (UINT, Token::UInt(7)),
            (REAL, Token::Real(7.5)),
            (STRING, Token::Str("7")),
            (BOOL, Token::Bool(true)),
        ];
        let scalar_kinds = NULL | INT | UINT | REAL | STRING | BOOL;
        let mut all = Vec::new();
        for owner in table::COMPONENTS.iter().chain(&table::EVENT_RESPONSES) {
            nodes(owner.members, &mut all);
        }
        let mut counted = [0usize; 4];
        for node in all {
            let (slot, declared) = match node.type_name {
                "int" => (
                    0,
                    Declared::Int {
                        bits: 32,
                        signed: true,
                    },
                ),
                "float" => (1, Declared::Float { bits: 32 }),
                "string" => (2, Declared::Text),
                "bool" => (3, Declared::Bool),
                _ => continue,
            };
            counted[slot] += 1;
            let takes = tokens
                .iter()
                .filter(|(_, token)| !matches!(judge(declared, *token, rules), Verdict::Refused(_)))
                .fold(0, |mask, (kind, _)| mask | kind);
            assert_eq!(
                node.accepts & scalar_kinds,
                takes,
                "a `{}` node takes {:#010b}, the profile {takes:#010b}",
                node.type_name,
                node.accepts
            );
        }
        // Every scalar node of the table is held: the components' and the event responses'.
        assert_eq!(counted, [243, 433, 233, 169]);
    }

    /// The version a migrated reader converts below is the crate's first typed version
    /// of the key (the conversion runs in the step that reaches it).
    #[test]
    fn a_migrated_reader_s_typed_version_is_the_crate_s_first_typed() {
        let mut wrong = Vec::new();
        for owner in components() {
            if let Some((a, b, c)) = owner.typed_since {
                let crate_first = crate::component::EntityComponent::typed_since(owner.name);
                if crate_first != Some(FormatVersion::new(a, b, c)) {
                    wrong.push(format!("{}: {a}.{b}.{c} vs {crate_first:?}", owner.name));
                }
            }
        }
        assert!(wrong.is_empty(), "{wrong:#?}");
    }

    /// Names are patterns matched whole: `a|b` and the one class the schemas use.
    #[test]
    fn a_name_pattern_matches_the_whole_name() {
        assert!(matches("feedItems|feed_items", "feed_items"));
        assert!(matches("feedItems|feed_items", "feedItems"));
        assert!(!matches("feedItems|feed_items", "feed_item"));
        assert!(matches("[a-zA-Z0-9_.:-]+", "demo:prop.a-1"));
        assert!(!matches("[a-zA-Z0-9_.:-]+", "a b"));
        assert!(!matches("[a-zA-Z0-9_.:-]+", ""));
    }

    /// An enum value is looked up lower-cased; one it does not know fails, with the keys as
    /// the game lists them.
    #[test]
    fn an_enum_value_is_looked_up_lower_cased() {
        static OPTIONS: [Node; 1] = [n("enumerated_value", STRING, &[], &[], &["easy", "hard"])];
        static MEMBERS: [Member; 1] = [Member {
            name: "min_difficulty",
            required: false,
            options: &OPTIONS,
        }];
        let ok = validate(
            &MEMBERS,
            &bedrock_addon_core::json::from_str_jsonc::<Value>(r#"{"min_difficulty": "HARD"}"#)
                .unwrap(),
            true,
        );
        assert!(!ok.failed && ok.problems.is_empty(), "{ok:?}");
        let bad = validate(
            &MEMBERS,
            &bedrock_addon_core::json::from_str_jsonc::<Value>(r#"{"min_difficulty": "extreme"}"#)
                .unwrap(),
            false,
        );
        assert!(bad.failed);
        let code = bad.problems[0].code();
        assert!(code.is(&codes::ENUM_NOT_ALLOWED));
        assert_eq!(
            codes::ENUM_NOT_ALLOWED.template(),
            "Value '{}' not allowed.  Must match at least one of the following keys: {}"
        );
        assert_eq!(code.args(), ["extreme", " easy\n or  hard\n"]);
    }

    /// A required child is checked only when the members passed validation.
    #[test]
    fn a_missing_required_child_fails_only_after_the_members_passed() {
        static OPTIONS: [Node; 1] = [n("string", STRING, &[], &[], &[])];
        static MEMBERS: [Member; 1] = [Member {
            name: "sound",
            required: true,
            options: &OPTIONS,
        }];
        let empty = validate(
            &MEMBERS,
            &bedrock_addon_core::json::from_str_jsonc::<Value>("{}").unwrap(),
            true,
        );
        assert!(empty.failed);
        assert!(matches!(
            empty.problems[..],
            [Problem::Missing { name: "sound", .. }]
        ));
        let unknown = validate(
            &MEMBERS,
            &bedrock_addon_core::json::from_str_jsonc::<Value>(r#"{"x": 1}"#).unwrap(),
            true,
        );
        assert!(matches!(unknown.problems[..], [Problem::Unknown { .. }]));
    }

    /// A document at `version` whose components hold `key` with `value`, and `beside`.
    fn document(version: &str, key: &str, value: &str, beside: &str) -> String {
        format!(
            r#"{{"format_version": "{version}", "minecraft:entity": {{"description": {{"identifier": "test:mob"}}, "components": {{"{key}": {value}{beside}}}}}}}"#
        )
    }

    /// The newest struct `text` loads to, written, with the findings; `None` when refused.
    fn load(text: &str) -> (Option<Value>, Diagnostics) {
        use bedrock_addon_core::document::Content;
        let loaded = bedrock_addon_core::versioning::load::<crate::Entity>(
            bedrock_addon_core::json::JsonSlice::new(text),
            &bedrock_addon_core::load::LoadContext::detached(),
        );
        let written = match &loaded.value {
            Some(bedrock_addon_core::versioning::Loaded::Stable(entity)) => entity
                .to_json()
                .ok()
                .and_then(|text| bedrock_addon_core::json::from_str_jsonc::<Value>(&text).ok()),
            _ => None,
        };
        (written, loaded.diagnostics)
    }

    /// For every component and goal of the table, an
    /// unknown member at a version its reader reads strictly (a never-migrated reader at
    /// 1.26.60, a migrated one at 1.20.0, below every typed version of the table) is one kept
    /// error with the game's text, no other warning or error is told, the component is written
    /// as its defaults and the entity loads.
    #[test]
    fn every_schema_reader_tells_an_unknown_member_and_keeps_its_defaults() {
        let mut wrong = Vec::new();
        for owner in components() {
            let version = if owner.typed_since.is_some() {
                "1.20.0"
            } else {
                "1.26.60"
            };
            let key = owner.name;
            // `spawn_egg_interaction` needs `offspring` beside it (a rule of the game's, not of
            // the schema).
            let beside = if key == "minecraft:spawn_egg_interaction" {
                r#", "minecraft:offspring": {}"#
            } else {
                ""
            };
            let (written, found) = load(&document(version, key, r#"{"zz_unknown": 1}"#, beside));
            let (plain, _) = load(&document(version, key, "{}", beside));
            let (Some(written), Some(plain)) = (written, plain) else {
                wrong.push(format!("{key} {version}: refused: {found:#?}"));
                continue;
            };
            let kept: Vec<(String, String)> = found
                .iter()
                .filter(|f| f.kept)
                .map(|f| (f.location.json_path.to_string(), f.code.to_string()))
                .collect();
            let expected = [(
                format!("minecraft:entity/components/{key}/zz_unknown"),
                "child 'zz_unknown' not valid here.".to_owned(),
            )];
            if kept != expected {
                wrong.push(format!("{key} {version}: {kept:?}"));
            }
            if let Some(f) = found
                .iter()
                .find(|f| f.severity >= Severity::Warning && !f.kept)
            {
                wrong.push(format!("{key} {version}: also {f:#?}"));
            }
            if written != plain {
                wrong.push(format!("{key} {version}: {written:?} is not {plain:?}"));
            }
        }
        assert!(wrong.is_empty(), "{}", wrong.join("\n"));
        assert_eq!(components().len(), 228);
    }

    /// One generated case per rendered text: for every numeric check of the legacy goal
    /// readers, a value just out of its bound in a 1.20.0 document is one kept error with the
    /// row's text and that value as the game prints it (`%d`, `%.4f`), and the goal is kept.
    #[test]
    fn every_legacy_goal_numeric_check_tells_its_text_and_keeps_the_goal() {
        use numeric::Kind;
        let mut wrong = Vec::new();
        let rows: Vec<_> = numeric_table::CHECKS
            .iter()
            .filter(|row| row.kind != Kind::Dependency)
            .collect();
        for row in &rows {
            #[allow(clippy::cast_possible_truncation, reason = "the bounds are small")]
            let (value, shown) = match row.kind {
                Kind::IntAtLeast => {
                    let v = row.bound as i64 - 1;
                    (v.to_string(), v.to_string())
                }
                Kind::IntAbove => {
                    let v = row.bound as i64;
                    (v.to_string(), v.to_string())
                }
                Kind::FloatAtLeast => {
                    let v = row.bound - 1.0;
                    (format!("{v:?}"), format!("{v:.4}"))
                }
                Kind::FloatAbove => (format!("{:?}", row.bound), format!("{:.4}", row.bound)),
                Kind::FloatUpTo => {
                    let v = row.bound + 1.0;
                    (format!("{v:?}"), format!("{v:.4}"))
                }
                Kind::Dependency => unreachable!("filtered"),
            };
            // `charge_held_item` requires `items` (a required child of its schema).
            let beside = if row.goal == "minecraft:behavior.charge_held_item" {
                r#", "items": ["minecraft:arrow"]"#
            } else {
                ""
            };
            let goal = format!(r#"{{"{}": {value}{beside}}}"#, row.member);
            let (written, found) = load(&document("1.20.0", row.goal, &goal, ""));
            if written.is_none() {
                wrong.push(format!("{} {}: refused: {found:#?}", row.goal, row.member));
                continue;
            }
            let kept: Vec<(String, String)> = found
                .iter()
                .filter(|f| f.kept)
                .map(|f| (f.location.json_path.to_string(), f.code.to_string()))
                .collect();
            let expected = [(
                format!("minecraft:entity/components/{}/{}", row.goal, row.member),
                row.template.replace("{}", &shown),
            )];
            if kept != expected {
                wrong.push(format!("{} {}: {kept:?}", row.goal, row.member));
            }
        }
        assert!(wrong.is_empty(), "{}", wrong.join("\n"));
        assert_eq!(rows.len(), 328);
    }

    /// A value the option takes, for the member test: of the first JSON type it accepts.
    fn sample(node: &Node) -> &'static str {
        if node.accepts & BOOL != 0 && node.accepts & (INT | REAL) == 0 {
            "true"
        } else if node.accepts & (INT | UINT | REAL) != 0 {
            "1"
        } else if node.accepts & STRING != 0 {
            r#""minecraft:apple""#
        } else if node.accepts & ARRAY != 0 && node.accepts & OBJECT == 0 {
            "[]"
        } else {
            "{}"
        }
    }

    /// Every spelling of every member a migrated component's legacy
    /// schema reader takes is a member of the crate's conversion: written alone with a value
    /// its first option takes, the crate does not tell it as unknown.
    #[test]
    fn the_crate_converts_every_member_of_the_legacy_readers() {
        let mut wrong = Vec::new();
        for owner in components().iter().filter(|o| o.typed_since.is_some()) {
            let key = owner.name;
            for member in owner.members {
                for spelling in member.name.split('|') {
                    let value = format!(r#"{{"{spelling}": {}}}"#, sample(&member.options[0]));
                    let (_, found) = load(&document("1.20.0", key, &value, ""));
                    for f in &found {
                        if f.code.name() == "UnrecognizedField" && !f.kept {
                            wrong.push(format!("{key}.{spelling}: {}", f.location.json_path));
                        }
                    }
                }
            }
        }
        assert!(wrong.is_empty(), "{}", wrong.join("\n"));
    }
}
